import fs from "node:fs";
import path from "node:path";

/**
 * Read param/model bytes from the data-only dh_model.wasm
 * (same layout as output/<role>/wasm/dh_model.mjs).
 */
export async function loadNcnnFromWasm(wasmPath) {
  const bytes = fs.readFileSync(wasmPath);
  const { instance } = await WebAssembly.instantiate(bytes, {});
  const exp = instance.exports;
  const mem = new Uint8Array(exp.memory.buffer);
  const po = Number(exp.paramOffset.value ?? exp.paramOffset);
  const pl = Number(exp.paramLength.value ?? exp.paramLength);
  const mo = Number(exp.modelOffset.value ?? exp.modelOffset);
  const ml = Number(exp.modelLength.value ?? exp.modelLength);
  return {
    paramBin: Buffer.from(mem.subarray(po, po + pl)),
    modelBin: Buffer.from(mem.subarray(mo, mo + ml)),
  };
}

export function materializeWeights(cacheDir, paramBin, modelBin) {
  fs.mkdirSync(cacheDir, { recursive: true });
  const paramPath = path.join(cacheDir, "dh_model.param");
  const binPath = path.join(cacheDir, "dh_model.bin");
  fs.writeFileSync(paramPath, paramBin);
  fs.writeFileSync(binPath, modelBin);
  return { paramPath, binPath };
}
